const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial = candidate => escape(Array.from(candidate.name || '?')[0]);
const face = candidate => candidate.avatarUrl && /^(https:\/\/|\/assets\/)/.test(candidate.avatarUrl) ? `<img class="bell-face" src="${escape(candidate.avatarUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer">` : initial(candidate);
const proximity = candidate => candidate.distanceKm===null?'距离未知':candidate.distanceKm===0?'同一粗略区域':'区域估算约 '+candidate.distanceKm+' km';
export function candidateDetail(candidate) {
  return `<div class="radar-detail"><div class="radar-avatar">${face(candidate)}</div><h2>${escape(candidate.name)}</h2><p>${escape([candidate.occupation,candidate.city||'未填写城市',candidate.age||'未填写年龄'].filter(Boolean).join(' · '))}</p><p>${escape(candidate.statement||'还没有自我介绍')}</p><div class="chips">${candidate.interests.map(i=>`<span class="pill">${escape(i)}</span>`).join('')}</div><div class="notice"><b>O 为什么推荐</b><p>${candidate.reasons.map(escape).join('<br>')}</p><p class="small muted">来自自填资料，匹配不代表身份核验或关系承诺。</p></div><p class="small muted">${escape(candidate.address)}</p><button class="btn" data-action="invite" data-address="${escape(candidate.address)}">发送 Ring 邀请</button></div>`;
}
function card(candidate, expanded) {
  return `<article class="radar-card ${expanded?'expanded':''}">${candidate.distanceKm!==null?`<span class="radar-distance" title="粗略区域估算距离">${candidate.distanceKm===0?'同一区域':'~'+candidate.distanceKm+' km'}</span>`:''}<button class="radar-save" data-action="radar-save" data-address="${escape(candidate.address)}" aria-label="${candidate.saved?'取消收藏':'收藏'} ${escape(candidate.name)}" aria-pressed="${candidate.saved}">${candidate.saved?'♥':'♡'}</button><button class="radar-person" data-action="radar-detail" data-address="${escape(candidate.address)}" aria-label="查看 ${escape(candidate.name)} 的资料"><div class="radar-avatar">${face(candidate)}</div><h3>${escape(candidate.name)}</h3><p class="small muted">${escape(candidate.city||'未填写城市')}${candidate.occupation?' · '+escape(candidate.occupation):''} · ${proximity(candidate)}</p></button><div class="chips">${candidate.interests.slice(0,expanded?8:2).map(i=>`<span class="pill">${escape(i)}</span>`).join('')}</div>${expanded?`<p>${candidate.reasons.map(escape).join(' · ')}</p><button class="btn" data-action="invite" data-address="${escape(candidate.address)}">发送邀请</button>`:''}</article>`;
}
export function radarView(state) {
  const radar=state.radar||{total:0,hasLocation:false},filters=state.radarFilters,candidates=state.candidates;
  const preview=candidates.slice(0,4),expanded=state.radarExpanded;
  const stage=state.radarScanning?'scanning':state.radarError?'error':!state.radar?'idle':radar.total?'results':'empty';
  return `<section class="radar-page" aria-labelledby="radar-title"><div class="radar-brand"><span class="radar-status">✦ Resonance Radar</span></div><div class="radar-heading"><h1 id="radar-title">Find someone <em>who<br>resonates.</em></h1><p>让共同的兴趣与真诚的心意，<br>在附近找到属于你的共鸣。</p></div><div class="radar-stage ${stage} ${Date.now()-(state.radarPulse||0)<1500?'resonating':''}" aria-busy="${Boolean(state.radarScanning)}"><div class="radar-sweep"></div><div class="radar-orbit orbit-one"></div><div class="radar-orbit orbit-two"></div><div class="radar-orbit orbit-three"></div><div class="radar-orbit orbit-four"></div><div class="radar-waves" aria-hidden="true"><i></i><i></i><i></i></div><div class="radar-shockwave" aria-hidden="true"></div><button class="radar-hub" type="submit" form="radar-search-form" aria-label="敲响铃铛，重新寻找共鸣" ${state.radarScanning?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 9a6 6 0 0 1 12 0c0 6 3 8 3 8H3s3-2 3-8Z"/><path d="M10 21h4M3 7 1 10M21 7l2 3"/></svg></button>${preview.map((candidate,index)=>`<button class="radar-satellite satellite-${index}" style="--reveal-delay:${[.3,1.5,2.4,3.5][index]}s" data-action="radar-detail" data-address="${escape(candidate.address)}" aria-label="查看 ${escape(candidate.name)} 的资料"><span class="radar-placeholder" aria-hidden="true"></span><span class="radar-node"><span class="radar-node-face">${initial(candidate)}</span><span class="radar-node-name">${escape(candidate.name)} <span aria-hidden="true">✦</span></span><span class="radar-resonance-dot" aria-hidden="true"></span></span></button>`).join('')}${!preview.length?[0,1,2,3].map(index=>`<span class="radar-idle-dot satellite-${index}" aria-hidden="true"></span>`).join(''):''}</div><form id="radar-search-form" class="radar-filters" data-form="radar"><div class="radar-filter-row"><label>城市<input name="city" maxlength="60" value="${escape(filters.city)}" placeholder="不限城市"></label><label>区域范围<select name="radius">${[0,20,50,100,200].map(km=>`<option value="${km}" ${filters.radius===km?'selected':''}>${km?km+' km':'不限距离'}</option>`).join('')}</select></label><label>关系意向<select name="intention">${[['','不限意向'],['Serious relationship','认真建立关系'],['Open to connection','先认识彼此'],['Already in love','已有伴侣'],['Just exploring','先探索一下'],...(!['','Serious relationship','Open to connection','Already in love','Just exploring'].includes(filters.intention)?[[filters.intention,filters.intention]]:[])].map(([value,label])=>`<option value="${escape(value)}" ${filters.intention===value?'selected':''}>${escape(label)}</option>`).join('')}</select></label></div><details class="radar-extra-filters"><summary>更多筛选 · 性别与年龄</summary><div class="radar-extra-row"><label>性别自述<input name="gender" maxlength="30" list="radar-gender-options" value="${escape(filters.gender||'')}" placeholder="不限 · 与对方自述一致才匹配"><datalist id="radar-gender-options"><option value="女"><option value="男"><option value="非二元"><option value="保密"></datalist></label><label>年龄区间<span class="age-range"><input name="ageMin" type="number" inputmode="numeric" min="18" max="99" aria-label="最小年龄" placeholder="从" value="${filters.ageMin||''}"><span aria-hidden="true">–</span><input name="ageMax" type="number" inputmode="numeric" min="18" max="99" aria-label="最大年龄" placeholder="至" value="${filters.ageMax||''}"></span></label></div><p class="small muted">性别与年龄筛选只作用于对方自愿公开的自述资料；自述缺失或与区间不符的人不会出现在结果里。</p></details><div class="radar-agent"><span aria-hidden="true">✦</span><div><b>CONSENSUS AGENT</b><p>${state.radarScanning?'正在寻找与你共鸣的人…':radar.total?'发现 '+radar.total+' 位可能共鸣的人':'从共同兴趣开始，寻找彼此的共鸣'}</p></div></div><button class="btn radar-cta" type="submit" ${state.radarScanning?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M6 9a6 6 0 0 1 12 0c0 6 3 8 3 8H3s3-2 3-8ZM10 20h4v2h-4Z"/></svg> ${state.radarScanning?'正在探测…':'Ring the Bell'}</button><p class="radar-action-note">敲响一声 Bell，让真诚的心意相遇。</p></form><section class="radar-results" aria-label="匹配结果" aria-live="polite"><div class="radar-result-head"><div><h2>${state.radarError?'探测暂时不可用':state.radarScanning?'O 正在寻找共鸣…':radar.total?'发现 '+radar.total+' 位可能共鸣的人':'还没有发现合适的人'}</h2><p class="small muted">${radar.total?'点击资料查看 O 的具体匹配理由。':'试试扩大范围，或先完善自己的兴趣与意向。'}</p></div>${candidates.length>4?`<button class="radar-more" data-action="radar-expand" aria-expanded="${Boolean(expanded)}">${expanded?'收起':'查看全部'}</button>`:''}</div>${state.radarInsight?`<aside class="bell-agent radar-insight"><div class="row"><span class="bell-agent-label">✦ O 的共鸣解读 · 附近最合适</span><span class="small muted">结构化规则引擎 · 非大模型</span></div><p>${escape(state.radarInsight.summary||'')}</p>${state.radarInsight.nearbyCount?`<small class="muted">其中 ${state.radarInsight.nearbyCount} 位在约 50 km 内（粗略区域估算）。</small>`:''}<div class="row">${escape('')}<button class="btn light compact" data-action="radar-agent-revoke">撤回解读授权</button></div></aside>`:(!state.radarScanning&&state.user&&!state.preview?`<div class="radar-insight-cta"><button class="btn light compact" data-action="radar-agent">✦ 让 O 解读附近最合适的人群</button></div>`:'')}${state.radarError?`<p role="alert" class="notice">${escape(state.radarError)}</p>`:''}<div class="radar-grid ${expanded?'all-results':''}">${(expanded?candidates:preview).map(c=>card(c,expanded)).join('')}</div>${!candidates.length?'<p class="radar-empty">这里只展示已登录并主动公开资料的真实用户。<br>不会用示例人物填满雷达。</p>':''}${radar.limited?'<p class="small muted">当前显示排名前 100 位，请缩小筛选范围。</p>':''}</section><div class="radar-location"><button class="btn light compact" data-action="${radar.hasLocation?'radar-revoke-location':'radar-location'}">${radar.hasLocation?'撤回附近定位':'开启附近定位'}</button><button class="btn light compact" data-action="identity">修改我的资料</button></div><p class="small muted radar-disclosure">O 当前按共同兴趣、意向、城市与人群筛选推荐，不承诺匹配成功。附近范围是粗略区域估算，并非精准距离；性别与年龄来自对方自述，未经核验。${state.profile?.discoverable?'你已允许其他登录用户发现你的公开资料。':'你尚未开启公开资料，其他人无法在雷达中发现你。'}</p></section>`;
}
