export const emptyProfile=()=>({name:'',city:'',gender:'',age:'',interests:[],statement:'',intention:'Serious relationship',discoverable:false,avatarUrl:'',occupation:''});
export const carryIdentityDraft=(existingProfile,visitorDraft)=>!existingProfile&&visitorDraft?{...visitorDraft,interests:[...(visitorDraft.interests||[])]}:null;
export const interestChoices=[['Music','音乐','in-music.webp'],['Travel','旅行','in-travel.webp'],['Photography','摄影','in-photo.webp'],['Food','美食','in-food.webp'],['Reading','阅读','in-reading.webp'],['Movies','电影','in-movies.webp'],['AI','AI','in-ai.webp'],['Art','艺术','in-art.webp'],['Sports','运动','in-sports.webp']];
export function updateIdentity(draft,step,fields){
  const next={...emptyProfile(),...draft,interests:[...(draft?.interests||[])]};
  if(step===1){for(const key of ['name','city','gender','age','avatarUrl','occupation'])next[key]=String(fields[key]||'').trim();if(!next.name)throw new Error('先告诉我们你的昵称。');if(next.name.length>40)throw new Error('昵称最多 40 个字。');if(next.avatarUrl&&!/^\/assets\/[a-zA-Z0-9._-]+$/.test(next.avatarUrl)){let ok=false;try{const u=new URL(next.avatarUrl);ok=u.protocol==='https:'&&!u.username&&!u.password;}catch{}if(!ok)throw new Error('头像链接必须是 HTTPS 图片地址（HTTPS only）。');}if(next.occupation.length>80)throw new Error('职业最多 80 个字。');}
  if(step===3)next.intention=String(fields.intention||next.intention).trim();
  if(step===4){next.statement=String(fields.statement||'').trim();next.discoverable=Boolean(fields.discoverable);if(next.statement.length>200)throw new Error('爱情宣言最多 200 个字。');}
  if(next.interests.length>8)throw new Error('最多选择八项兴趣。');return next;
}
